import React, { useState, useEffect } from 'react';
import {
  Container,
  Typography,
  Paper,
  Grid,
  Card,
  CardContent,
  Button,
  Box,
  Chip,
  Alert,
  CircularProgress,
  Table,
  TableBody,
  TableCell,
  TableContainer,
  TableHead,
  TableRow,
  Drawer,
  AppBar,
  Toolbar,
  List,
  ListItem,
  ListItemButton,
  ListItemIcon,
  ListItemText,
  Divider
} from '@mui/material';
import {
  People as PeopleIcon,
  School as SchoolIcon,
  Business as BusinessIcon,
  Assignment as AssignmentIcon,
  Work as WorkIcon,
  TrendingUp as TrendingUpIcon,
  Dashboard as DashboardIcon,
  AddBusiness as AddBusinessIcon,
  LibraryBooks as LibraryBooksIcon,
  Assessment as AssessmentIcon
} from '@mui/icons-material';
import { useAuth } from '../context/AuthContext';
import { useNavigate, useLocation, Outlet } from 'react-router-dom';
import { adminAPI } from '../services/api';

const drawerWidth = 280;

const menuItems = [
  { text: 'Dashboard', icon: <DashboardIcon />, path: '/admin' },
  { text: 'User Management', icon: <PeopleIcon />, path: '/admin/users' },
  { text: 'Institutions', icon: <SchoolIcon />, path: '/admin/institutions' },
  { text: 'Company Approval', icon: <BusinessIcon />, path: '/admin/companies' },
  { text: 'System Reports', icon: <AssessmentIcon />, path: '/admin/reports' },
  { text: 'Add Institution', icon: <AddBusinessIcon />, path: '/admin/add-institution' },
  { text: 'Add Faculty', icon: <SchoolIcon />, path: '/admin/add-faculty' },
  { text: 'Add Course', icon: <LibraryBooksIcon />, path: '/admin/add-course' },
];

const AdminDashboard = () => {
  const { currentUser } = useAuth();
  const navigate = useNavigate();
  const location = useLocation();
  const [stats, setStats] = useState(null);
  const [recentActivities, setRecentActivities] = useState([]);
  const [pendingCompanies, setPendingCompanies] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState('');

  useEffect(() => {
    // Only fetch dashboard data if we're on the main admin dashboard
    if (location.pathname === '/admin') {
      fetchDashboardData();
    }
  }, [location.pathname]);

  const fetchDashboardData = async () => {
    try {
      setLoading(true);
      const response = await adminAPI.getDashboardStats();
      setStats(response.data.stats);
      setRecentActivities(response.data.recentActivities || []);
      setPendingCompanies(response.data.pendingCompanies || []);
    } catch (err) {
      setError('Failed to load dashboard data');
    } finally {
      setLoading(false);
    }
  };

  const StatCard = ({ title, value, icon, color = 'primary' }) => (
    <Card>
      <CardContent>
        <Box sx={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between' }}>
          <Box>
            <Typography color="textSecondary" gutterBottom variant="overline">
              {title}
            </Typography>
            <Typography variant="h4" component="div">
              {value}
            </Typography>
          </Box>
          <Box sx={{ color: `${color}.main` }}>
            {icon}
          </Box>
        </Box>
      </CardContent>
    </Card>
  );

  // If we're on a nested route (like /admin/users), render the nested component
  if (location.pathname !== '/admin') {
    return (
      <Box sx={{ display: 'flex' }}>
        {/* Sidebar Drawer */}
        <Drawer
          variant="permanent"
          sx={{
            width: drawerWidth,
            flexShrink: 0,
            [`& .MuiDrawer-paper`]: {
              width: drawerWidth,
              boxSizing: 'border-box',
            },
          }}
        >
          <Toolbar>
            <Typography variant="h6" noWrap component="div">
              Admin Panel
            </Typography>
          </Toolbar>
          <Divider />
          <Box sx={{ overflow: 'auto' }}>
            <List>
              {menuItems.map((item) => (
                <ListItem key={item.text} disablePadding>
                  <ListItemButton
                    selected={location.pathname === item.path}
                    onClick={() => navigate(item.path)}
                  >
                    <ListItemIcon>
                      {item.icon}
                    </ListItemIcon>
                    <ListItemText primary={item.text} />
                  </ListItemButton>
                </ListItem>
              ))}
            </List>
          </Box>
        </Drawer>

        {/* Main Content Area for Nested Routes */}
        <Box component="main" sx={{ flexGrow: 1, p: 3 }}>
          <Toolbar />
          <Outlet /> {/* This renders the nested admin pages */}
        </Box>
      </Box>
    );
  }

  // Main Dashboard Content (only for /admin route)
  if (loading) {
    return (
      <Box sx={{ display: 'flex' }}>
        <Drawer
          variant="permanent"
          sx={{
            width: drawerWidth,
            flexShrink: 0,
            [`& .MuiDrawer-paper`]: {
              width: drawerWidth,
              boxSizing: 'border-box',
            },
          }}
        >
          <Toolbar>
            <Typography variant="h6" noWrap component="div">
              Admin Panel
            </Typography>
          </Toolbar>
          <Divider />
          <Box sx={{ overflow: 'auto' }}>
            <List>
              {menuItems.map((item) => (
                <ListItem key={item.text} disablePadding>
                  <ListItemButton
                    selected={location.pathname === item.path}
                    onClick={() => navigate(item.path)}
                  >
                    <ListItemIcon>
                      {item.icon}
                    </ListItemIcon>
                    <ListItemText primary={item.text} />
                  </ListItemButton>
                </ListItem>
              ))}
            </List>
          </Box>
        </Drawer>
        
        <Box component="main" sx={{ flexGrow: 1, p: 3 }}>
          <Toolbar />
          <Container maxWidth="lg" sx={{ display: 'flex', justifyContent: 'center', alignItems: 'center', minHeight: '50vh' }}>
            <Box textAlign="center">
              <CircularProgress size={60} />
              <Typography variant="h6" sx={{ mt: 2 }}>Loading Admin Dashboard...</Typography>
            </Box>
          </Container>
        </Box>
      </Box>
    );
  }

  return (
    <Box sx={{ display: 'flex' }}>
      {/* Sidebar Drawer */}
      <Drawer
        variant="permanent"
        sx={{
          width: drawerWidth,
          flexShrink: 0,
          [`& .MuiDrawer-paper`]: {
            width: drawerWidth,
            boxSizing: 'border-box',
          },
        }}
      >
        <Toolbar>
          <Typography variant="h6" noWrap component="div">
            Admin Panel
          </Typography>
        </Toolbar>
        <Divider />
        <Box sx={{ overflow: 'auto' }}>
          <List>
            {menuItems.map((item) => (
              <ListItem key={item.text} disablePadding>
                <ListItemButton
                  selected={location.pathname === item.path}
                  onClick={() => navigate(item.path)}
                >
                  <ListItemIcon>
                    {item.icon}
                  </ListItemIcon>
                  <ListItemText primary={item.text} />
                </ListItemButton>
              </ListItem>
            ))}
          </List>
        </Box>
      </Drawer>

      {/* Main Dashboard Content */}
      <Box component="main" sx={{ flexGrow: 1, p: 3 }}>
        <Toolbar />
        <Container maxWidth="lg">
          <Typography variant="h4" gutterBottom>
            Admin Dashboard
          </Typography>
          
          {error && (
            <Alert severity="error" sx={{ mb: 2 }} onClose={() => setError('')}>
              {error}
            </Alert>
          )}

          {/* Statistics Grid */}
          <Grid container spacing={3} sx={{ mb: 4 }}>
            <Grid item xs={12} sm={6} md={3}>
              <StatCard
                title="Total Students"
                value={stats?.students || 0}
                icon={<PeopleIcon fontSize="large" />}
                color="primary"
              />
            </Grid>
            <Grid item xs={12} sm={6} md={3}>
              <StatCard
                title="Institutions"
                value={stats?.institutions || 0}
                icon={<SchoolIcon fontSize="large" />}
                color="secondary"
              />
            </Grid>
            <Grid item xs={12} sm={6} md={3}>
              <StatCard
                title="Companies"
                value={stats?.companies || 0}
                icon={<BusinessIcon fontSize="large" />}
                color="success"
              />
            </Grid>
            <Grid item xs={12} sm={6} md={3}>
              <StatCard
                title="Applications"
                value={stats?.applications || 0}
                icon={<AssignmentIcon fontSize="large" />}
                color="warning"
              />
            </Grid>
          </Grid>

          <Grid container spacing={3}>
            {/* Quick Actions */}
            <Grid item xs={12} md={6}>
              <Card>
                <CardContent>
                  <Typography variant="h6" gutterBottom>
                    Quick Actions
                  </Typography>
                  <Box sx={{ display: 'flex', flexDirection: 'column', gap: 2 }}>
                    <Button 
                      variant="contained" 
                      onClick={() => navigate('/admin/users')}
                      startIcon={<PeopleIcon />}
                    >
                      Manage Users
                    </Button>
                    <Button 
                      variant="outlined" 
                      onClick={() => navigate('/admin/institutions')}
                      startIcon={<SchoolIcon />}
                    >
                      Manage Institutions
                    </Button>
                    <Button 
                      variant="outlined" 
                      onClick={() => navigate('/admin/companies')}
                      startIcon={<BusinessIcon />}
                      disabled={!pendingCompanies.length}
                    >
                      Approve Companies ({pendingCompanies.length})
                    </Button>
                    <Button 
                      variant="outlined" 
                      onClick={() => navigate('/admin/reports')}
                      startIcon={<TrendingUpIcon />}
                    >
                      View Reports
                    </Button>
                    <Button 
                      variant="outlined" 
                      onClick={() => navigate('/admin/add-institution')}
                      startIcon={<SchoolIcon />}
                    >
                      Add New Institution
                    </Button>
                  </Box>
                </CardContent>
              </Card>
            </Grid>

            {/* System Overview */}
            <Grid item xs={12} md={6}>
              <Card>
                <CardContent>
                  <Typography variant="h6" gutterBottom>
                    System Overview
                  </Typography>
                  <Typography variant="body2" color="textSecondary" gutterBottom>
                    Welcome, System Administrator
                  </Typography>
                  <Typography variant="body2" color="textSecondary" gutterBottom>
                    Email: {currentUser?.email}
                  </Typography>
                  <Typography variant="body2" color="textSecondary" gutterBottom>
                    Role: {currentUser?.role}
                  </Typography>
                  
                  <Box sx={{ mt: 2, display: 'flex', flexWrap: 'wrap', gap: 1 }}>
                    <Chip label={`${stats?.faculties || 0} Faculties`} size="small" />
                    <Chip label={`${stats?.courses || 0} Courses`} size="small" />
                    <Chip label={`${stats?.jobs || 0} Jobs`} size="small" />
                    <Chip 
                      label={`${pendingCompanies.length} Pending Companies`} 
                      color="warning" 
                      size="small" 
                    />
                  </Box>
                </CardContent>
              </Card>
            </Grid>

            {/* Pending Companies */}
            {pendingCompanies.length > 0 && (
              <Grid item xs={12} md={6}>
                <Card>
                  <CardContent>
                    <Typography variant="h6" gutterBottom color="warning.main">
                      Pending Company Approvals
                    </Typography>
                    <TableContainer>
                      <Table size="small">
                        <TableHead>
                          <TableRow>
                            <TableCell>Company Name</TableCell>
                            <TableCell>Industry</TableCell>
                            <TableCell>Action</TableCell>
                          </TableRow>
                        </TableHead>
                        <TableBody>
                          {pendingCompanies.slice(0, 3).map((company) => (
                            <TableRow key={company.id}>
                              <TableCell>{company.name}</TableCell>
                              <TableCell>{company.industry}</TableCell>
                              <TableCell>
                                <Button
                                  size="small"
                                  onClick={() => navigate('/admin/companies')}
                                >
                                  Review
                                </Button>
                              </TableCell>
                            </TableRow>
                          ))}
                        </TableBody>
                      </Table>
                    </TableContainer>
                    {pendingCompanies.length > 3 && (
                      <Button 
                        size="small" 
                        onClick={() => navigate('/admin/companies')}
                        sx={{ mt: 1 }}
                      >
                        View All ({pendingCompanies.length})
                      </Button>
                    )}
                  </CardContent>
                </Card>
              </Grid>
            )}

            {/* Recent Activities */}
            <Grid item xs={12} md={6}>
              <Card>
                <CardContent>
                  <Typography variant="h6" gutterBottom>
                    Recent Activities
                  </Typography>
                  {recentActivities.length > 0 ? (
                    <TableContainer>
                      <Table size="small">
                        <TableHead>
                          <TableRow>
                            <TableCell>User</TableCell>
                            <TableCell>Role</TableCell>
                            <TableCell>Action</TableCell>
                          </TableRow>
                        </TableHead>
                        <TableBody>
                          {recentActivities.map((activity) => (
                            <TableRow key={activity.id}>
                              <TableCell>{activity.email}</TableCell>
                              <TableCell>
                                <Chip label={activity.role} size="small" />
                              </TableCell>
                              <TableCell>{activity.action}</TableCell>
                            </TableRow>
                          ))}
                        </TableBody>
                      </Table>
                    </TableContainer>
                  ) : (
                    <Typography variant="body2" color="textSecondary">
                      No recent activities
                    </Typography>
                  )}
                </CardContent>
              </Card>
            </Grid>

            {/* Admin Features */}
            <Grid item xs={12}>
              <Card>
                <CardContent>
                  <Typography variant="h6" gutterBottom>
                    Administrative Controls
                  </Typography>
                  <Typography variant="body2" color="textSecondary">
                    As an administrator, you have access to:
                  </Typography>
                  <Grid container spacing={2} sx={{ mt: 1 }}>
                    <Grid item xs={12} sm={6} md={3}>
                      <Typography variant="body2">
                        • Manage all user accounts
                      </Typography>
                    </Grid>
                    <Grid item xs={12} sm={6} md={3}>
                      <Typography variant="body2">
                        • Approve company registrations
                      </Typography>
                    </Grid>
                    <Grid item xs={12} sm={6} md={3}>
                      <Typography variant="body2">
                        • Monitor institutions & courses
                      </Typography>
                    </Grid>
                    <Grid item xs={12} sm={6} md={3}>
                      <Typography variant="body2">
                        • Generate system reports
                      </Typography>
                    </Grid>
                  </Grid>
                </CardContent>
              </Card>
            </Grid>
          </Grid>
        </Container>
      </Box>
    </Box>
  );
};

export default AdminDashboard;
